def main():
    findings=[]
    supplemental=json.loads((OUT/'SUPPLEMENTAL-LICENSE-EVIDENCE.json').read_text(encoding='utf-8'))['sources']
    supplement_map={3:['mastra-root','mastra-ee'],8:['litellm-ee-actual'],20:['activepieces-ee'],22:['langfuse-ee'],31:['infisical-ee-actual']}
    for rank,review in REVIEWS.items():
        cache=BASE/f'work/github-cache/{rank}.json'
        a=json.loads(cache.read_text(encoding='utf-8'))
        refs=[]
        for resource in a['resources']:
            d=resource.get('data',{})
            content=d.get('content')
            if isinstance(content,str):
                refs.append({'kind':resource['kind'],'url':resource['url'],'blob_sha':d.get('sha'),'observed_content_sha256':hashlib.sha256(content.encode()).hexdigest(),'content_characters':len(content),'scope':'SOURCE_TEXT_ONLY'})
        findings.append({'rank':rank,'requested_repo':a['repo'],'canonical_repo':a['canonical_repo'],'head':a['head'],'cache_sha256':hashlib.sha256(cache.read_bytes()).hexdigest(),'checked_at':'2026-11-12',**review,'evidence_refs':refs,'supplemental_license_refs':[s for s in supplemental if s['key'] in supplement_map.get(rank,[])],'inspection_status':'README_AND_LICENSE_TEXT_REVIEWED','license_status':'TEXT_SCOPE_INSPECTED_NOT_PACKAGE_OR_ENTITLEMENT_CLEARANCE','runtime_verification':'NOT_RUN','security_audit':'NOT_PERFORMED','awe_acceptance':'NOT_PROVEN','cross_family_review':'NOT_SATISFIED'})
    assert len(findings)==19 and all(any(x['kind']=='readme' for x in f['evidence_refs']) for f in findings)
    assert len(supplemental)==6
    output={'status':'PARTIAL','reviewer':'separate independent agent, same GPT family','method':'Manual review of 19 pinned source README/license caches plus six supplemental license texts. No code executed, no service configured, no paid API called. Cached metadata may differ from text; text controls the recorded licensing scope.','reviewed_ranks':list(REVIEWS),'reviewed_count':len(findings),'findings':findings,'critical_do_not_infer':['README description or GitHub metadata is not sandbox/security/production certification.','A permissive root license does not cover excluded enterprise directories, hosted terms, dependencies or model/provider access.','MCP is a protocol; source descriptions do not grant execution or write authorization.','Model routing software is not inference credit, payment eligibility, quality assurance or a verified hard budget.','An independent agent in the same GPT family does not satisfy the requested different-family gate.']}
    (OUT/'HIGH-RISK-FINDINGS.json').write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    lines=['# Independent high-risk source review','','Status: **PARTIAL**. Separate auditor, same GPT family. The different-family requirement remains **NOT_SATISFIED**. All nineteen requested high-risk candidates have source-text review; none received runtime, security, production, APPROVED or INTEGRATED certification.','','The review uses pinned README/license caches and six additional pinned licensing sources. Machine-readable details, source URLs, blob SHAs and cache checksums are in `HIGH-RISK-FINDINGS.json` and `SUPPLEMENTAL-LICENSE-EVIDENCE.json`. No upstream code was run; no live credentials were used.','','## Critical conclusions','','- Agent Zero metadata says NOASSERTION, but the inspected root license text is MIT. NOASSERTION is a classifier result, not absence of a license.','- Mastra, LiteLLM, Activepieces, Langfuse and Infisical are mixed core/enterprise repositories. Core permissive terms must not be applied to excluded EE features. n8n has Sustainable Use plus Enterprise terms.','- MCP Inspector and reference servers are in an MIT-to-Apache-2.0 transition with distinct documentation terms. Reference-server ownership does not establish production readiness.','- Playwright MCP and origin filters explicitly do not form a security boundary. Inspector may store secrets unencrypted when keychain support is absent.','- The current Google Workspace CLI is explicitly not an officially supported Google product. Community bridges require their own OAuth, scope and tenant-isolation tests.','- OpenSandbox records a current release signing/provenance gap. OpenHands local execution and optional conversation sandboxes must not be confused with full service/host isolation.','- Hermes README antivirus exclusions and free-tier/router headlines remain untrusted operational or promotional assertions. No antivirus protection, trust store, runtime or provider account was changed.','','## Findings by candidate','']
    for row in findings:
        readme=next((r['url'] for r in row['evidence_refs'] if r['kind']=='readme'),f"https://github.com/{row['canonical_repo']}/tree/{row['head']}")
        lines += [f"### {row['rank']}. {row['canonical_repo']}",'',f"Source: [pinned README]({readme}); HEAD `{row['head']}`.",'',f"**License scope.** {row['license']}",'',f"**Documented facts.** {row['facts']}",'',f"**Do not infer.** {row['do_not_infer']}",'',f"**Minimum next pilot.** {row['pilot']}",'']
    lines += ['## Historical hash result','','The local source QA literal hash comparison is an **explained historical byte mismatch**, not an upstream content failure. The committed files contain LF and match pinned Git blobs; the old report hashes match a CRLF reconstruction exactly. The report retains both facts instead of manufacturing a byte-equality PASS.','','## Remaining acceptance gates','','All pilot descriptions above are proposed tests, **NOT_RUN**. Primary-source review supports integration planning only. Dependency/source-code audits, actual OS/backend compatibility, pricing/entitlement, account scopes, malicious-input tests, recovery and independent runtime QA remain pending. The same-family review cannot close the cross-family gate.']
    (OUT/'HIGH-RISK-REVIEW.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(json.dumps({'reviewed':len(findings),'status':'PARTIAL','rank_set':list(REVIEWS)},ensure_ascii=False))

if __name__=='__main__': main()
